/** Cent Companion logo — inlined for OG image (Pages esbuild has no image loader). */
const LOGO_JPEG_BASE64 = "";

let cachedLogoDataUrl: string | null = null;

export function getLogoDataUrl(): string {
  if (cachedLogoDataUrl) return cachedLogoDataUrl;
  cachedLogoDataUrl = `data:image/jpeg;base64,${LOGO_JPEG_BASE64}`;
  return cachedLogoDataUrl;
}
